//! schemars-nixgen: Generate Nix option definitions from JSON Schema
//!
//! This library converts JSON Schema (as generated by schemars) into
//! strongly-typed Nix option definitions for the NixOS module system.

pub mod format;
pub mod generator;
pub mod prepare;
pub mod types;

pub use generator::Generator;
pub use generator::GeneratorError;
pub use generator::GeneratorOptions;
pub use types::NixOption;
pub use types::NixType;

use schemars::JsonSchema;
use serde_json::Value;

/// Extension trait for generating Nix options from types that implement JsonSchema
pub trait SchemaExt: JsonSchema {
    /// Generate Nix module code for this type
    fn to_nix_options(options: &GeneratorOptions) -> Result<String, GeneratorError> {
        let schema = schemars::schema_for!(Self);
        let schema_value: Value = serde_json::to_value(&schema)
            .map_err(|e| GeneratorError::InvalidSchema(e.to_string()))?;
        let mut generator = Generator::new(&schema_value);
        generator.generate(&schema_value, options)
    }
}

// Implement SchemaExt for all types that implement JsonSchema
impl<T: JsonSchema> SchemaExt for T {}

/// Generate Nix options from a JSON schema value
pub fn generate_from_schema(
    schema: &Value,
    options: &GeneratorOptions,
) -> Result<String, GeneratorError> {
    let mut generator = Generator::new(schema);
    generator.generate(schema, options)
}

/// Generate Nix options from a JSON schema string
pub fn generate_from_str(
    schema_str: &str,
    options: &GeneratorOptions,
) -> Result<String, GeneratorError> {
    let schema: Value = serde_json::from_str(schema_str)
        .map_err(|e| GeneratorError::InvalidSchema(e.to_string()))?;
    generate_from_schema(&schema, options)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn test_generate_from_schema() {
        let schema = json!({
            "type": "object",
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "description": "Whether to enable the feature"
                },
                "count": {
                    "type": "integer",
                    "description": "Number of items"
                }
            }
        });

        let options = GeneratorOptions {
            root_name: "myapp".to_string(),
            root_description: "My application configuration".to_string(),
        };

        let output = generate_from_schema(&schema, &options).unwrap();

        assert!(output.contains("{ lib, ... }:"));
        assert!(output.contains("options.myapp"));
        assert!(output.contains("lib.types.bool"));
        assert!(output.contains("lib.types.int"));
        assert!(output.contains("Whether to enable the feature"));
    }

    #[test]
    fn test_generate_from_str() {
        let schema_str = r#"{
            "type": "object",
            "properties": {
                "name": {"type": "string"}
            }
        }"#;

        let options = GeneratorOptions::default();
        let output = generate_from_str(schema_str, &options).unwrap();

        assert!(output.contains("lib.types.str"));
    }
}
